async def act(page):
    """
    Dismiss any blocking dialog, click the scoped Search control to apply the
    currently-selected filters (Status is already set to 'Pending' in the UI),
    then scan the Orders grid for the first/top row whose Status contains
    'Pending' and return its Order # string.

    This function intentionally does not call any knowledge-base helpers because
    those helpers operate on the Dashboard "Last Orders" widget (Customer,
    Items, Grand Total) or snapshot/date helpers and do not expose order
    increment IDs or Status values from the full Sales > Orders grid.
    """
    # 1) Dismiss any dialog/overlay if present (use accessibility roles)
    try:
        if await page.get_by_role('dialog').count() > 0:
            dlg = page.get_by_role('dialog').nth(0)
            # Try to click a labeled close button inside the dialog if present
            try:
                if await dlg.get_by_role('button', name='×').count() > 0:
                    await dlg.get_by_role('button', name='×').nth(0).click()
                    await page.wait_for_timeout(300)
                elif await dlg.get_by_role('button', name='Close').count() > 0:
                    await dlg.get_by_role('button', name='Close').nth(0).click()
                    await page.wait_for_timeout(300)
                elif await dlg.get_by_role('button').count() > 0:
                    # fallback: click the first button inside the dialog
                    await dlg.get_by_role('button').nth(0).click()
                    await page.wait_for_timeout(300)
            except Exception:
                # if a specific click failed, try pressing Escape
                try:
                    await page.keyboard.press('Escape')
                    await page.wait_for_timeout(300)
                except Exception:
                    pass
    except Exception:
        # tolerate any failures dismissing a dialog
        pass

    # 2) Ensure tables exist
    tables = page.get_by_role('table')
    if await tables.count() == 0:
        await page.wait_for_timeout(1000)
        if await tables.count() == 0:
            raise RuntimeError('No tables found on the page to inspect for orders')

    # 3) Find the control table that contains the Reset Filter / Search cell
    control_table = None
    try:
        candidates = page.get_by_role('table').filter(
            has=page.get_by_role('cell', name='Reset Filter Search')
        )
        if await candidates.count() > 0:
            control_table = candidates.nth(0)
    except Exception:
        control_table = None

    # 4) Click Search scoped to the control table if possible, otherwise global Search
    search_clicked = False
    if control_table is not None:
        try:
            if await control_table.get_by_role('button', name='Search').count() > 0:
                await control_table.get_by_role('button', name='Search').nth(0).click()
                await page.wait_for_load_state('networkidle')
                await page.wait_for_timeout(500)
                search_clicked = True
        except Exception:
            search_clicked = False

    if not search_clicked:
        try:
            if await page.get_by_role('button', name='Search').count() > 0:
                await page.get_by_role('button', name='Search').nth(0).click()
                await page.wait_for_load_state('networkidle')
                await page.wait_for_timeout(500)
        except Exception:
            pass

    # 5) Locate the Orders grid table (table whose header contains the link 'Order #')
    orders_table = None
    try:
        orders_candidates = page.get_by_role('table').filter(
            has=page.get_by_role('link', name='Order #')
        )
        if await orders_candidates.count() > 0:
            orders_table = orders_candidates.nth(0)
    except Exception:
        orders_table = None

    if orders_table is None:
        # fallback to first table
        tables = page.get_by_role('table')
        if await tables.count() == 0:
            raise RuntimeError('No tables available to treat as Orders grid')
        orders_table = tables.nth(0)

    # helper to scan a table for the first row that contains 'Pending'
    async def scan_for_pending(table_loc):
        rows = table_loc.get_by_role('row')
        try:
            row_count = await rows.count()
        except Exception:
            return None
        for i in range(row_count):
            row = rows.nth(i)
            try:
                text = (await row.inner_text()).strip()
            except Exception:
                continue
            # skip header/filter rows heuristically
            if ('Order #' in text and 'Status' in text) or ('From:' in text and 'To :' in text):
                continue
            if 'Pending' in text:
                # Attempt to read Order # from cell index 1
                cells = row.get_by_role('cell')
                try:
                    cell_count = await cells.count()
                except Exception:
                    cell_count = 0
                order_id = None
                if cell_count > 1:
                    try:
                        order_id = (await cells.nth(1).inner_text()).strip()
                    except Exception:
                        order_id = None
                if not order_id:
                    try:
                        links = row.get_by_role('link')
                        if await links.count() > 0:
                            order_id = (await links.nth(0).inner_text()).strip()
                    except Exception:
                        order_id = None
                if order_id:
                    return order_id
                return text
        return None

    # 6) Scan and return if found
    result = await scan_for_pending(orders_table)
    if result:
        print(result)
        return result

    # 7) If not found, try explicitly selecting Status='Pending' in comboboxes and re-search
    comboboxes = page.get_by_role('combobox')
    try:
        cb_count = await comboboxes.count()
    except Exception:
        cb_count = 0
    applied = False
    for j in range(cb_count):
        cb = comboboxes.nth(j)
        try:
            await cb.select_option(label='Pending')
            applied = True
            await page.wait_for_timeout(300)
            break
        except Exception:
            continue

    if applied:
        # click Search again (scoped preferred)
        if control_table is not None:
            try:
                if await control_table.get_by_role('button', name='Search').count() > 0:
                    await control_table.get_by_role('button', name='Search').nth(0).click()
                    await page.wait_for_load_state('networkidle')
                    await page.wait_for_timeout(500)
            except Exception:
                pass
        else:
            try:
                if await page.get_by_role('button', name='Search').count() > 0:
                    await page.get_by_role('button', name='Search').nth(0).click()
                    await page.wait_for_load_state('networkidle')
                    await page.wait_for_timeout(500)
            except Exception:
                pass

        # re-locate orders table and re-scan
        try:
            orders_candidates = page.get_by_role('table').filter(
                has=page.get_by_role('link', name='Order #')
            )
            if await orders_candidates.count() > 0:
                orders_table = orders_candidates.nth(0)
            else:
                tables = page.get_by_role('table')
                orders_table = tables.nth(0)
        except Exception:
            tables = page.get_by_role('table')
            orders_table = tables.nth(0)

        result = await scan_for_pending(orders_table)
        if result:
            print(result)
            return result

    # 8) If still not found, raise an informative error
    raise RuntimeError('No pending orders found in the Orders grid')

